  @route_options {:object, %{times: {:times, nil}}}

  @typedoc "Options of `route/4`, see its docs."
  @type route_options :: [times: integer()] | %{optional(:times) => integer()}

  @doc ~S"""
  Routing provides the capability to modify network requests that are made by any page in the browser context. Once route
  is enabled, every request matching the url pattern will stall unless it's continued, fulfilled or aborted.

  > #### Note {: .info}
  >
  > `PlaywrightEx.BrowserContext.route/4` will not intercept requests intercepted by Service Worker. See [this](https://github.com/microsoft/playwright/issues/1090) issue. We recommend disabling Service Workers when using request interception by setting `:service_workers` to `:block`.

  **Usage**

  An example of a naive handler that aborts all image requests:

  ```elixir
  context = Browser.new_context!(browser)
  BrowserContext.route!(context, "**/*.{png,jpg,jpeg}", &Route.abort/1)
  page = BrowserContext.new_page!(context)
  Page.goto!(page, "https://example.com")
  Browser.close!(browser)
  ```

  or the same snippet using a regex pattern instead:

  ```elixir
  context = Browser.new_context!(browser)
  BrowserContext.route!(context, ~r/(\.png$)|(\.jpg$)/, &Route.abort/1)
  page = BrowserContext.new_page!(context)
  Page.goto!(page, "https://example.com")
  Browser.close!(browser)
  ```

  It is possible to examine the request to decide the route action. For example, mocking all requests that contain some post data, and leaving all other requests as is:

  ```elixir
  BrowserContext.route!(context, "/api/**", fn route ->
    if Route.request(route) |> Request.post_data() |> String.contains?("my-string") do
      Route.fulfill!(route, body: "mocked-data")
    else
      Route.continue!(route)
    end
  end)
  ```

  Page routes (set up with `PlaywrightEx.Page.route/4`) take precedence over browser context routes when request matches both
  handlers.

  To remove a route with its handler you can use `PlaywrightEx.BrowserContext.unroute/3`.

  > #### Note {: .info}
  >
  > Enabling routing disables http cache.

  *Since Playwright 1.8.*

  ## Arguments

  * `url` - A glob pattern, regex pattern, URL pattern, or predicate that receives a `URL` to match during routing. If `:base_url` is set in the context options and the provided URL is a string that does not start with `*`, it is resolved using the [`new URL()`](https://developer.mozilla.org/en-US/docs/Web/API/URL/URL) constructor.
  * `handler` - handler function to route the request.

  ## Options

  * `:times` (`t:integer/0`) - *Since Playwright 1.15.* How often a route should be used. By default it will be used every time.
  """
  @spec route(
          t(),
          String.t() | Regex.t() | PlaywrightEx.RegExp.t() | (String.t() -> boolean()),
          (PlaywrightEx.Route.t() -> term()) | (PlaywrightEx.Route.t(), PlaywrightEx.Request.t() -> term()),
          route_options()
        ) :: {:ok, PlaywrightEx.Disposable.t()} | {:error, PlaywrightEx.error()}
  def route(browser_context, url, handler, options \\ []) do
    options = Facade.options!(options, @route_options, "browserContext.route")

    Facade.async("browserContext.route", browser_context, fn ->
      PlaywrightEx.Client.BrowserContext.route(browser_context, url, handler, options)
    end)
  end

  @doc "Like `route/4`, but returns the value and raises on error."
  @spec route!(
          t(),
          String.t() | Regex.t() | PlaywrightEx.RegExp.t() | (String.t() -> boolean()),
          (PlaywrightEx.Route.t() -> term()) | (PlaywrightEx.Route.t(), PlaywrightEx.Request.t() -> term()),
          route_options()
        ) :: PlaywrightEx.Disposable.t()
  def route!(browser_context, url, handler, options \\ []) do
    options = Facade.options!(options, @route_options, "browserContext.route")

    Facade.async!("browserContext.route", browser_context, fn ->
      PlaywrightEx.Client.BrowserContext.route(browser_context, url, handler, options)
    end)
  end

